import { NextRequest, NextResponse } from "next/server";
import { authorizeRequest } from "@/lib/apiTokens";
import { uploadMediaLibraryImage } from "@/lib/r2Upload";
import { ALLOWED_IMAGE_TYPES } from "@/lib/imagePolicy";
import { generateImage, ImageGenerationError, imageGenerationStatus } from "@/lib/imageGeneration";
import { unauthorized } from "@/lib/pagesApi";

/** Generate an image from a prompt and put it straight into the Media
 * Library, returning its URL. One call, because the two halves are
 * useless apart: a client that could hold the generated bytes could have
 * uploaded them in the first place.
 *
 * Image generation runs on this server, with this deployment's own
 * provider key, specifically so a hosted chat client can use it. An image
 * such a client generates with its own built-in tool has no public URL to
 * hand over, and its bytes cannot leave through a tool call -- so the
 * prompt has to be the thing that travels. See src/lib/imageGeneration.ts.
 *
 * Generation takes real time on the larger models, so this route is
 * deliberately slow rather than queued: an MCP tool call can wait, and a
 * job id the caller has to poll would be a worse trade for one image. */
export const maxDuration = 300;

export async function GET(req: NextRequest) {
  const auth = await authorizeRequest(req, "media:read");
  if (!auth.ok) return unauthorized();
  return NextResponse.json(imageGenerationStatus());
}

export async function POST(req: NextRequest) {
  const auth = await authorizeRequest(req, "media:write");
  if (!auth.ok) return unauthorized();

  const body = (await req.json().catch(() => null)) as {
    prompt?: unknown;
    provider?: unknown;
    model?: unknown;
    width?: unknown;
    height?: unknown;
    quality?: unknown;
    transparent?: unknown;
    folder?: unknown;
    alt?: unknown;
    title?: unknown;
    filename?: unknown;
  } | null;

  const prompt = typeof body?.prompt === "string" ? body.prompt.trim() : "";
  if (!prompt) {
    return NextResponse.json({ error: "prompt is required: describe the image to generate." }, { status: 400 });
  }

  const dimension = (value: unknown): number | undefined => {
    const n = typeof value === "string" ? Number(value) : value;
    return typeof n === "number" && Number.isFinite(n) && n >= 16 && n <= 4096 ? Math.round(n) : undefined;
  };
  const quality = body?.quality === "low" || body?.quality === "medium" || body?.quality === "high" ? body.quality : undefined;

  let generated;
  try {
    generated = await generateImage({
      prompt,
      provider: typeof body?.provider === "string" ? body.provider : undefined,
      model: typeof body?.model === "string" ? body.model : undefined,
      width: dimension(body?.width),
      height: dimension(body?.height),
      quality,
      transparent: body?.transparent === true,
    });
  } catch (error) {
    if (error instanceof ImageGenerationError) {
      // 502, not 400: with a valid prompt the failure is the upstream
      // provider's, and a caller should be able to tell "your request was
      // wrong" from "the generator is down" without reading the prose.
      return NextResponse.json({ error: error.message, ...imageGenerationStatus() }, { status: 502 });
    }
    throw error;
  }

  const extension = ALLOWED_IMAGE_TYPES[generated.contentType];
  const slug = prompt.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 60) || "generated";
  const filename = (typeof body?.filename === "string" && body.filename.trim()) || `${slug}.${extension}`;
  const file = new File([Uint8Array.from(generated.bytes)], filename, { type: generated.contentType });

  const result = await uploadMediaLibraryImage(file, typeof body?.folder === "string" && body.folder ? body.folder : "page-images", {
    // The prompt is the only description that exists at this point, so it
    // becomes the alt text unless the caller wrote a better one -- an
    // image with no alt text at all is the worse default.
    alt: typeof body?.alt === "string" && body.alt.trim() ? body.alt : prompt,
    title: typeof body?.title === "string" ? body.title : undefined,
  });
  if ("error" in result) return NextResponse.json({ error: result.error }, { status: 400 });

  return NextResponse.json(
    { ...result, provider: generated.provider, model: generated.model, bytes: generated.bytes.length, prompt },
    { status: 201 }
  );
}
